import smbus2
import time

bus = smbus2.SMBus(1)

def read_word(address, register):
    h = bus.read_byte_data(address, register)
    l = bus.read_byte_data(address, register+1)
    value = (h << 8) + l
    return value

def read_word_2c(address, register):
    val = read_word(address, register)
    if (val >= 0x8000):
        return -((65535 - val) + 1)
    else:
        return val

def read_gyro_data(address):
    x = read_word_2c(address, 0x43)
    y = read_word_2c(address, 0x45)
    z = read_word_2c(address, 0x47)
    return [x, y, z]

def read_accel_data(address):
    x = read_word_2c(address, 0x3b)
    y = read_word_2c(address, 0x3d)
    z = read_word_2c(address, 0x3f)
    return [x, y, z]

def read_temp_data(address):
    temp = read_word_2c(address, 0x41)
    return temp

def read_all_data(address):
    temp = read_temp_data(address)
    accel = read_accel_data(address)
    gyro = read_gyro_data(address)
    return [temp, accel, gyro]

def main():
    try:
        while True:
            data = read_all_data(0x68)
            print(data)
            time.sleep(0.01)
    except KeyboardInterrupt:
        print("Exiting")
    finally:
        bus.close()

if __name__ == "__main__":
    main()

